532	  const sigText = await readFileUtf8(sigAbs);
533	  const sigB64 = sigText.replace(/\s+/g, '');
534	  let sigBuf;
535	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
536	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
537	  }
538	  try {
539	    sigBuf = Buffer.from(sigB64, 'base64');
540	  } catch {
541	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
542	  }
543	  if (sigBuf.length !== 64) {
544	    throw new ProvError(
545	      ERROR_CODES.PROOF_INVALID,
546	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
547	    );
548	  }
