561	      ERROR_CODES.KEY_NOT_FOUND,
562	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
563	      {
564	        providedKeyFingerprint: providedFingerprint,
565	        proofKeyFingerprint: proof.signerKeyFingerprint,
566	      },
567	    );
