634	// SBOM 校验：结构 -> 摘要 -> 签名 -> 清单一致性。
635	async function verifySbom({ sbomAbs, sbomSigAbs, proof, publicKey }) {
636	  // a) sbom.json 必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
637	  const sbomText = await readFileUtf8(sbomAbs);
638	  let sbom;
639	  try {
640	    sbom = JSON.parse(sbomText);
641	  } catch {
642	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 文件不是合法的 JSON');
643	  }
644	  const sbomError = validateSbom(sbom);
645	  if (sbomError) {
646	    throw new ProvError(ERROR_CODES.PROOF_INVALID, sbomError);
647	  }
648	
649	  // b) 证明必须携带合法的 sbomDigest 字段。
650	  if (typeof proof.sbomDigest !== 'string' || !/^[0-9a-f]{64}$/i.test(proof.sbomDigest)) {
651	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明缺少合法的 sbomDigest 字段');
652	  }
653	
654	  // c) 重算 SBOM 规范字节摘要并与证明比对 —— 不一致说明 sbom.json 被替换或改动。
655	  const canonicalSbom = stableJsonStringify(sbom);
656	  const recomputed = sha256Hex(canonicalSbom);
657	  if (recomputed.toLowerCase() !== proof.sbomDigest.toLowerCase()) {
658	    throw new ProvError(
659	      ERROR_CODES.INTEGRITY_MISMATCH,
660	      'sbom.json 与证明记录的 sbomDigest 不一致（SBOM 可能被替换）',
661	      { mismatches: [{ path: 'sbom.json', kind: 'content-modified' }] },
662	    );
663	  }
664	
665	  // d) SBOM 签名：合法 Base64 且 64 字节 —— 否则 PROOF_INVALID；验签失败 SIGNATURE_INVALID。
666	  const sigText = await readFileUtf8(sbomSigAbs);
667	  const sigB64 = sigText.replace(/\s+/g, '');
668	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
669	    throw new ProvError(ERROR_CODES.PROOF_INVALID, 'SBOM 签名文件不是合法的 Base64 内容');
670	  }
671	  const sigBuf = Buffer.from(sigB64, 'base64');
672	  if (sigBuf.length !== 64) {
673	    throw new ProvError(
674	      ERROR_CODES.PROOF_INVALID,
675	      `SBOM 签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
676	    );
677	  }
678	  let sigOk = false;
679	  try {
680	    sigOk = cryptoVerify(null, Buffer.from(canonicalSbom, 'utf8'), publicKey, sigBuf);
681	  } catch {
682	    sigOk = false;
683	  }
684	  if (!sigOk) {
685	    throw new ProvError(
686	      ERROR_CODES.SIGNATURE_INVALID,
687	      'SBOM 签名与 sbom.json 内容不匹配（SBOM 可能被改动，或签名已损坏）',
688	    );
689	  }
690	
691	  // e) SBOM 清单与证明清单逐项一致（证明与当前扫描已在前面比对，故三方一致）。
692	  const mismatches = diffSbomAgainstProof(sbom, proof);
693	  if (mismatches.length > 0) {
694	    throw new ProvError(
695	      ERROR_CODES.INTEGRITY_MISMATCH,
696	      `SBOM 与证明清单存在 ${mismatches.length} 处差异`,
697	      { mismatches },
698	    );
699	  }
700	
701	  return recomputed;
702	}
