704	function inferExcludeDir(proofAbs, artifactAbs) {
705	  // 证明文件所在目录若位于产物之内，则将其视为生成时的输出目录予以排除。
706	  const proofDir = dirname(proofAbs);
707	  if (isWithin(proofDir, artifactAbs)) return proofDir;
708	  return null;
709	}
