776	// 返回差异列表；每条 {path, kind}。顶层摘要差异兜底。
777	function diffManifest(proof, currentSbom, currentDigest) {
778	  const mismatches = [];
779	  const proofFiles = new Map(proof.files.map((f) => [f.path, f]));
780	  const currentFiles = new Map(currentSbom.files.map((f) => [f.path, f]));
781	
782	  for (const [path, pf] of proofFiles) {
783	    const cur = currentFiles.get(path);
784	    if (!cur) {
785	      mismatches.push({ path, kind: 'missing' }); // 证明中存在、产物中已删除
786	      continue;
787	    }
788	    if (cur.sha256.toLowerCase() !== pf.sha256.toLowerCase()) {
789	      mismatches.push({ path, kind: 'content-modified' });
790	    } else if (cur.size !== pf.size) {
791	      mismatches.push({ path, kind: 'size-mismatch' });
792	    }
793	  }
794	  for (const path of currentFiles.keys()) {
795	    if (!proofFiles.has(path)) {
796	      mismatches.push({ path, kind: 'added' }); // 产物中新出现的文件
797	    }
798	  }
799	
800	  if (proof.artifactDigest.toLowerCase() !== currentDigest.toLowerCase() && mismatches.length === 0) {
801	    // 理论上不会发生（逐文件比对已覆盖），作为顶层摘要兜底。
802	    mismatches.push({ path: '.', kind: 'artifact-digest-mismatch' });
803	  }
804	  if (proof.fileName !== currentSbom.artifactName) {
805	    mismatches.push({ path: '.', kind: 'artifact-name-mismatch' });
806	  }
807	
808	  mismatches.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : a.kind < b.kind ? -1 : 1));
809	  return mismatches;
810	}
