869	function daysInMonth(year, month) {
870	  // month: 1-12
871	  if (month === 2) {
872	    return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0) ? 29 : 28;
873	  }
874	  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
875	}
